window.addEventListener("scroll",()=>{const t=document.documentElement.scrollTop,e=document.documentElement.scrollHeight-window.innerHeight;document.getElementById("pbar").style.width=t/e*100+"%"});function toggleFaq(t){const e=t.parentElement,n=e.classList.contains("open");document.querySelectorAll(".faq-item.open").forEach(o=>o.classList.remove("open")),n||e.classList.add("open")}
